<?php
namespace App\Http\Controllers\Parent;
use App\Http\Controllers\Controller; use App\Models\Child; use App\Models\CourseSchedule; use App\Services\ScheduleConflictService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class BookingController extends Controller {
 public function store(Request $r, ScheduleConflictService $svc){$d=$r->validate(['child_id'=>'required|exists:children,id','schedule_id'=>'required|exists:course_schedules,id']);$child=Child::where('parent_id',$r->user()->id)->findOrFail($d['child_id']);$schedule=CourseSchedule::with('course')->findOrFail($d['schedule_id']);$conf=$svc->conflicts($child,$schedule);if($conf)return back()->with('conflicts',$conf)->with('alternatives',$svc->alternatives($schedule))->withInput();DB::transaction(function()use($r,$child,$schedule){$e=$child->enrollments()->create(['parent_id'=>$r->user()->id,'course_id'=>$schedule->course_id,'schedule_id'=>$schedule->id,'status'=>'pending_payment','enrolled_at'=>now()]);$e->transaction()->create(['parent_id'=>$r->user()->id,'invoice_code'=>'SP-'.now()->format('Ymd').'-'.strtoupper(Str::random(6)),'subtotal'=>$schedule->course->price,'platform_fee'=>15000,'total'=>$schedule->course->price+15000,'status'=>'pending']);});return redirect()->route('parent.dashboard')->with('success','Booking dibuat. Silakan lanjutkan pembayaran.');}
}
